import type { Scene } from "./timeline.d";

export const timeline: Scene[] = [{"id":"ghf-06500101-1","date":"0650-01-01","year":"c.650","location":"St Dochdwy's, Llandough","locationType":"other","description":"","narration":"St Dochdwy's church, beside the farm, is thought to stand on the site of an early monastery. This rests on the family's account; the published reference is still awaited, and how the site relates to the two parcels is unclear.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Archaeology and Heritage (greathousefarmwiki.wordpress.com/archaeology/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-11000101-1","date":"1100-01-01","year":"1100","location":"Llandough, Glamorgan","locationType":"other","description":"","narration":"Robert Fitzhamon grants the lordship of Llandough to the Walsche family, establishing feudal control of the area that includes the future Great House Farm.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-12000101-1","date":"1200-01-01","year":"1200s","location":"Llandough Church","locationType":"other","description":"","narration":"The site beside St Dochdwy's church at Llandough is occupied in the medieval period: sherds of 12th- to early 14th-century pottery were later found on the slope just north-east of the house. The house itself, Tŷ Mawr ('Great House'), was classed by the Royal Commission as a sub-medieval house, probably 17th-century, possibly with a medieval core.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-12150101-1","date":"1215-01-01","year":"1215","location":"Monastic Estate","locationType":"other","description":"","narration":"Tewkesbury Abbey and the Prior of Cardiff hold Great House and its lands, taking tithes and agricultural income from Llandough for over three centuries.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-12150102-1","date":"1215-01-02","year":"1215","location":"Great House Site — NE Slope","locationType":"other","description":"","narration":"Archaeological evidence confirms medieval occupation of the Great House site: sherds of C12th, C13th and early C14th pottery on the steep slope immediately NE of the house. The HER classifies Great House as a sub-medieval direct-entry house with clear affinities to Brynwell, a medieval farmhouse in neighbouring Leckwith parish. A reported 'armour' find is dealt with under c.1870 and c.1880.","scenes":[],"sources":["GGAT HER PRN 02038s via Archwilio","RCAHMW Inventory Vol IV Part 2","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":["Sherds of C12th, C13th, and early C14th pottery found on steep slope immediately NE of house","House classified as sub-medieval direct-entry type with cross-passage end-chimney plan","External wall batter on N side — affinities with Brynwell farmhouse in Leckwith (medieval, pre-Reformation)","Ogee-stopped beam with torus — a form of decoration not particularly common in Glamorgan (Inventory Map 50)"],"report":[]}},{"id":"ghf-14440101-1","date":"1444-01-01","year":"1444","location":"Raglan","locationType":"other","description":"","narration":"Sir William Thomas Herbert of Raglan purchases the manor and lordship of Llandough and St Mary Church, bringing them into the Herbert family's territorial network.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-15360101-1","date":"1536-01-01","year":"1536","location":"Legal Chambers","locationType":"other","description":"","narration":"Sir Edward Carne, a lawyer and diplomat, purchases the Llandough lordship from the 2nd Earl of Worcester, continuing high‑status lay ownership of the manor.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-15390101-1","date":"1539-01-01","year":"1539","location":"Great House","locationType":"other","description":"","narration":"Henry VIII's Dissolution of the Monasteries transfers Tewkesbury's ecclesiastical holdings, including Llandough lands, to the Crown as secular property.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-15430101-1","date":"1543-01-01","year":"1543","location":"Estate Office","locationType":"other","description":"","narration":"Post‑Dissolution grants move Llandough through lay owners and into the wider Herbert–Pembroke orbit, later feeding into what becomes the Bute estate.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-15520101-1","date":"1552-01-01","year":"1552","location":"Manorial Court","locationType":"other","description":"","narration":"The Bute–Pembroke estate treats itself as manorial lord, issuing leases for Llandough Farm (about 166 acres) and recording long‑standing occupiers as tenants.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-15600101-1","date":"1560-01-01","year":"1560","location":"Great House Farm","locationType":"other","description":"","narration":"The Vaughan family, a minor gentry family, become the chief freehold farmers of Great House from the mid C16th. They occupy the property for over two centuries, until the late C18th. Several memorial inscriptions relating to the family are preserved in Llandough parish church and churchyard. The Vaughans represent the established local gentry class who held the chief freehold farm of the parish for generations.","scenes":[],"sources":["GGAT HER PRN 02038s via Archwilio"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":["Vaughan family: minor gentry family, chief freehold farmers from mid C16th to late C18th","Several memorial inscriptions in Llandough church and churchyard"],"report":[]}},{"id":"ghf-16670101-1","date":"1667-01-01","year":"1667","location":"Great House Farm","locationType":"other","description":"","narration":"According to Mary Williams's own statement, the Williams family's occupation of Great House begins in 1667. No earlier written source has yet been found; family tradition remembers the entry as a purchase, while estate records treat the family as tenants.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: The family contend that their occupation from 1667 amounted to ownership in all but name, and that this claim was asserted for more than 300 years. An earlier written source is still being sought."},{"id":"ghf-16770101-1","date":"1677-01-01","year":"1677","location":"Estate Records","locationType":"other","description":"","narration":"Through marriage, the Llandough lordship passes into the Talbot estate at Penrice and Margam, while the Williams family continues in occupation at Great House.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-17700101-1","date":"1770-01-01","year":"1770","location":"Estate Transfer","locationType":"other","description":"","narration":"Great House passes through elite owners, including Valentine Morris and Sir Mark Wood, before later consolidation into the Bute estate.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-17940101-1","date":"1794-01-01","year":"1794","location":"Title Office","locationType":"other","description":"","narration":"Sir Mark Wood acquires title and treats Great House as a revenue asset within his wider property portfolio, before it is surveyed and later taken into Bute hands.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-18000101-1","date":"1800-01-01","year":"1800","location":"Great House","locationType":"other","description":"","narration":"In the early C19th, the freehold of Great House is acquired by the Bute Estate — one of the largest landed estates in Wales, controlled by the Marquess of Bute. The manorial courts for Llandough and Leckwith are held in Great House, confirming its historic role as a seat of local governance. The Bute Estate modernises the property in the C19th, as it did with neighbouring Brynwell farmhouse in Leckwith.","scenes":[],"sources":["GGAT HER PRN 02038s via Archwilio","RCAHMW Inventory Vol IV Part 2"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":["Bute Estate acquired freehold in early C19th","Manorial courts for Llandough and Leckwith held in Great House","Bute Estate modernised the house in the C19th"],"report":[]}},{"id":"ghf-18180101-1","date":"1818-01-01","year":"1818","location":"Estate Records","locationType":"other","description":"","narration":"Lambert Williams of Cardiff enters formal written agreements with the Bute estate between 1818 and 1835, evidencing the Williams family as a recognised legal entity in local property dealings.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-18180101-2","date":"1818-01-01","year":"1818","location":"Estate Accounts","locationType":"other","description":"","narration":"Chief rents of Llandough are transferred into the manorial rental accounts, simplifying estate bookkeeping and packaging obligations for future buyers.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-18200101-1","date":"1820-01-01","year":"1820","location":"Estate Offices","locationType":"other","description":"","narration":"A land exchange between the Marquess of Bute and Lord Plymouth in Llandough consolidates Great House within Bute's controlled block of estates.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-18210101-1","date":"1821-01-01","year":"1821","location":"Rent Collection","locationType":"other","description":"","narration":"Llandough and Cogan appear in Bute rentals from 1821 onward, consolidating manorial rents under a single administrative ledger controlled by the estate.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-18240101-1","date":"1824-01-01","year":"1824","location":"Survey Office","locationType":"other","description":"","narration":"Following Sir Mark Wood's property auction, surveyor David Stewart records Great House Farm under the alias 'Cedfin' in the Bute estate survey of Glamorgan holdings.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-18400101-1","date":"1840-01-01","year":"1840","location":"Estate Registry","locationType":"other","description":"","narration":"Census and tithe records use changing descriptions including 'Great House' and 'Great House Farm'. The family interpret the change as part of a wider loss of the property's historic status, but the records do not by themselves prove an intentional 'downgrading'.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: The family contend that re-describing Tŷ Mawr from manorial court house to farm house eroded their standing and obscured the property's significance."},{"id":"ghf-18580101-1","date":"1858-01-01","year":"1858","location":"Llandough Church Farm","locationType":"other","description":"","narration":"About 1858, while foundations are dug for new buildings at Llandough Church Farm, workmen find a medieval iron spearhead and a rowel spur, with about six skeletons. The bones are reburied near the stile on the south side of the church. The finds lie in the 100-metre square beside the church that also holds the 1994 cemetery site.","scenes":[],"sources":["GHF-E106-R33-A1 — 1931 letter, Museum Wales file 63.24 (https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e106-r33-a1-1931-letter-museum-wales-file-63-24/)","Archaeology and Heritage (https://greathousefarmwiki.wordpress.com/archaeology/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-18700101-1","date":"1870-01-01","year":"c.1870","location":"Great House — Dining Room","locationType":"other","description":"","narration":"Family tradition holds that a soldier in armour, with horse, lance and small shield, was found under the dining-room floor. A Daily Telegraph article of 16 April 1974 dates the find to 'about 1870', and RCAHMW holds a note of the story. No primary record of the find has been located; Museum Wales says the similar medieval objects in its collection came from Church Farm, Llandough, in 1858.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: The family regard the tradition as evidence of the site's antiquity that was never investigated. The Wiki records it as a documented tradition, not a proven find."},{"id":"ghf-18760101-1","date":"1876-01-01","year":"1876","location":"Estate Offices","locationType":"other","description":"","narration":"From 1876 the Bute Estate lets about 33 acres that had formed part of Great House Farm for the Llandough Limeworks, which work until about 1912. How that land relates to the family's two parcels is still being tested.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: The family allege they permitted quarrying in exchange for absolute freehold of their land parcel. This oral agreement was never formally recorded — a pattern of convenient documentation gaps."},{"id":"ghf-18770101-1","date":"1877-01-01","year":"1877","location":"Bute Estate Office","locationType":"other","description":"","narration":"Mary's statement records that the Bute Estate serves notice to quit, then sells the farmhouse and about 10 acres to the quarryman Daniel Thomas, keeping about 9 acres of fields. The Williams family hold tenancies from both. On the family's reconstruction this creates two parcels: the house (Parcel A) and the eastern fields (Parcel B). The deed is missing.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: The family contend the 1877 sale took the house parcel out of the Bute title chain for good, so it never passed to WGR or BP. The deed is missing, and the claim is being tested against the records."},{"id":"ghf-18771106-1","date":"1877-11-06","year":"1877","location":"Glamorgan Archives","locationType":"other","description":"","narration":"On 6 November 1877 the Bute Estate grants John Williams a counterpart lease. On the family's reconstruction it covers the fields (Parcel B). The lease is held at Glamorgan Archives and is still to be obtained.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-18800101-1","date":"1880-01-01","year":"1880","location":"Estate Records","locationType":"other","description":"","narration":"Later records use different descriptions for the property, including 'Court House', 'Grange' and 'Farm'. The family interpret this changing nomenclature as obscuring the site's historic status; the Wiki treats that interpretation as a contention, not a proven motive.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-18800101-2","date":"1880-01-01","year":"1880","location":"Great House — Rear Wing","locationType":"other","description":"","narration":"R.F. Suggett's December 1988 note in the HER records a report of 'armour' found under the floor of the rear wing c.1880, and suggests it may be the medieval ironwork at the National Museum. Museum Wales has since said those objects were found at Church Farm, Llandough, in 1858, and that it holds nothing similar from Great House Farm.","scenes":[],"sources":["GGAT HER PRN 02038s via Archwilio — Supplementary Notes (R.F. Sugget, December 1988)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":["Suggett (Dec 1988): report of 'armour' under rear-wing floor c.1880; may be the medieval ironwork at the National Museum","Amgueddfa Cymru (2026): the objects are stated to have been found at Church Farm, Llandough, in 1858","Museum holds nothing similar from Great House Farm"],"report":[]}},{"id":"ghf-18911111-1","date":"1891-11-11","year":"1891","location":"Llandough — Court Report","locationType":"other","description":"","narration":"On 11 November 1891 three geese are stolen from \"Mr. John Williams, Great House Farm, Llandough\". The newspaper report of the court case is contemporary evidence that John Williams was occupying the farm.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Press Archive — Newspaper Transcripts (greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n01) — GHF-E090-N01"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-18970501-1","date":"1897-05-01","year":"1897","location":"Great House Farm / Lavernock Point","locationType":"other","description":"","narration":"Family tradition holds that Thomas Williams of Great House carted Guglielmo Marconi and his equipment to Lavernock Point, where Marconi's May 1897 trials sent wireless signals across the Bristol Channel to Flat Holm. The trials are independently documented; the family's part in them has not yet been proved.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19050223-1","date":"1905-02-23","year":"1905","location":"HM Land Registry — WA231076 File","locationType":"other","description":"","narration":"A Bute conveyance dated 23 February 1905 later appears on the WA231076 registration file and is noted on the woodland title WA735527. On the wiki's current interpretation it concerns Parcel A; what it conveyed has still to be confirmed.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Land Registry Titles (greathousefarmwiki.wordpress.com/land-registry-titles/#deeds-before-registration)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19080101-1","date":"1908-01-01","year":"1908","location":"Great House Farm","locationType":"other","description":"","narration":"Mary's grandfather dies, and John Williams takes over both tenancies, the house from the Thomas side and the fields from Bute (Mary's statement).","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19100101-1","date":"1910-01-01","year":"1910–11","location":"Frederick Buckler — Birth","locationType":"other","description":"","narration":"Frederick Buckler is born in 1910 or 1911. The year is worked back from his death in 1967 at the age of 56; his birth and death certificates are still awaited.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Frederick Buckler (greathousefarmwiki.wordpress.com/frederick-buckler/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19130810-1","date":"1913-08-10","year":"1913","location":"Great House Farm","locationType":"other","description":"","narration":"Mary Williams is born at Great House Farm on 10 August 1913, the daughter of John Williams. She lives there all her life.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19160201-1","date":"1916-02-01","year":"1916","location":"Great House Farm, Llandough","locationType":"other","description":"","narration":"In February 1916 the Bute Estate lets the whole farm to John Williams on a yearly tenancy. The tenancy is known from the 1987 judgment and the 1989 Commission decision; no original document has been located.","scenes":[{"character":"ARCHIVIST","icon":"archive","side":"left","color":"#999","text":"This later becomes important because the 1939 plan is said to depict fields rather than the farmhouse parcel. The phrase 'whole farm' in later records therefore cannot by itself establish the precise land comprised in the tenancy without the original plan and instrument.","position":{"x":0,"y":0}}],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19240515-1","date":"1924-05-15","year":"1924","location":"HM Land Registry — WA231076 File","locationType":"other","description":"","narration":"An agreement dated 15 May 1924 appears on the WA231076 registration file. Its contents and effect are unknown, and it is not yet clear which parcel it concerns.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Land Registry Titles (greathousefarmwiki.wordpress.com/land-registry-titles/#deeds-before-registration)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19280101-1","date":"1928-01-01","year":"1928","location":"Great House Farm","locationType":"other","description":"","narration":"The last quarry machinery leaves, and Mary recalled that a final rent of about £4 was paid to Alfred Thomas in 1928. She also recalled that her father then regarded the farm as his own. The receipt is missing.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: The family contend that twelve years' rent-free occupation of the house parcel from 1928 was complete by about 1940."},{"id":"ghf-19311122-1","date":"1931-11-22","year":"1931","location":"Cogan Pill","locationType":"other","description":"","narration":"On 22 November 1931 a letter headed Cogan Pill records the 1858 Church Farm finds for the National Museum. The spur and spearhead are later donated in 1963 and accessioned as 63.24. In 2026 the Museum will at first say it holds nothing relevant.","scenes":[],"sources":["GHF-E106-R33 — Museum Wales reply (https://greathousefarmwiki.wordpress.com/records-access-chronology/foi-reply-register/ghf-e106-r33-amgueddfa-cymru-reply-further-collections-search-following-8-september-2026-foi/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19360101-1","date":"1936-01-01","year":"1936","location":"Great House Farm","locationType":"other","description":"","narration":"Mary Williams marries Frederick Buckler, who joins her at the farmhouse. They have seven children, among them William (Billy). After Frederick's death in 1967 Mary reverts to her maiden name, Williams.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19370101-1","date":"1937-01-01","year":"c.1937–40","location":"Great House Farm","locationType":"other","description":"","narration":"Frederick and Mary's eldest son is born at about this time. The date rests on family belief; his birth entry has still to be traced.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — The Williams / Buckler Family (greathousefarmwiki.wordpress.com/williams-buckler-family/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19380101-1","date":"1938-01-01","year":"1938","location":"Bute Estate Office","locationType":"other","description":"","narration":"The Bute Estate conveys its reversion on the 1916 tenancy to Western Ground Rents Ltd (WGR). The family reconstruction contends that the house parcel had already passed out of Bute hands in 1877, so the exact land comprised in the 1938 conveyance must be tested against the earlier transaction and the 1939 tenancy plan.","scenes":[{"character":"ARCHIVIST","icon":"archive","side":"left","color":"#999","text":"The significance is a title-chain fork: if the 1877 transaction included the farmhouse parcel, the 1938 'reversion' cannot simply be assumed to include it.","position":{"x":0,"y":0}}],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19390501-1","date":"1939-05-01","year":"1939","location":"Great House Farm","locationType":"other","description":"","narration":"In May 1939 WGR grants John Williams a revised tenancy. Its plan shows the fields east of the house. The family contend it covered the eastern fields (Parcel B) only, not the farmhouse.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19400101-1","date":"1940-01-01","year":"c.1940","location":"Great House Farm","locationType":"other","description":"","narration":"The family contend that by about 1940 twelve years of rent-free occupation of the house parcel, counted from the last rent paid in 1928, would have been complete.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — 1938–39: Sale to WGR and the Revised Tenancy (greathousefarmwiki.wordpress.com/1939-revised-tenancy/#c1940)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: This is the family's contention. It depends on the house parcel being outside the 1916 and 1939 tenancies after 1928, which is still being tested against the records."},{"id":"ghf-19440101-1","date":"1944-01-01","year":"1944","location":"Great House Farm","locationType":"other","description":"","narration":"The War Agricultural Executive Committee is dissatisfied with the farm, and Frederick Buckler runs it as manager for John Williams (Mary's statement).","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19480101-1","date":"1948-01-01","year":"c.1948–49","location":"Great House Farm","locationType":"other","description":"","narration":"William (Billy) Buckler is born at the farm. He lives there until the eviction of 1988.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — The Williams / Buckler Family (greathousefarmwiki.wordpress.com/williams-buckler-family/#william)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19490202-1","date":"1949-02-02","year":"1949","location":"Great House Farm, Llandough","locationType":"other","description":"","narration":"On 2 February 1949 John Williams’s existing tenancy was surrendered and WGR intended a new yearly agricultural tenancy for his son-in-law, Frederick Buckler, from the same date. The 1987 judgment says the tenancy was intended to be put in writing, but that never happened; WGR’s agents later wrote on 10 October 1952 that they did not propose to proceed with the letting. The surviving 1939 written tenancy plan is the clearest identified plan and shows the eastern fields, not the farmhouse. Mary is not named as a tenant in the 1949 arrangement. The evidence therefore raises a material question: was an eastern-fields tenancy subsequently described as a tenancy of the ‘farm’ in a way that blurred the boundary between the two parcels?","scenes":[],"sources":["Great House Farm Wiki — Frederick Buckler, 1949 tenancy: https://greathousefarmwiki.wordpress.com/frederick-buckler/#tenancy-1949","Great House Farm Wiki — 1938–39 Revised Tenancy: https://greathousefarmwiki.wordpress.com/1939-revised-tenancy/","Great House Farm Wiki — Two Parcels: https://greathousefarmwiki.wordpress.com/the-two-parcels/"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"FAMILY INTERPRETATION: The family sees the 1949 change as one possible mechanism by which the eastern-fields tenancy could later be made to appear equivalent to occupation of the whole farm. That is a theory about the documentary narrative, not a proven motive. The priority is to obtain the original 1949/1952 papers and establish the precise demise and plan."},{"id":"ghf-19500601-1","date":"1950-06-01","year":"1950","location":"Great House Farm — Blanket Box","locationType":"other","description":"","narration":"In June 1950 a Penarth estate agent places a lodger at the farmhouse. He stays about two years, and later tells Mary he took 'the papers which were in the blanket box including the agreement relating to the farm' and gave them to the agent. Mary links the loss to WGR's first possession application.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: The family contend the documents that proved their title were taken from their home shortly before the first possession proceedings."},{"id":"ghf-19521010-1","date":"1952-10-10","year":"1952","location":"Landlords' Agents' Office","locationType":"other","description":"","narration":"On 10 October 1952 the landlords' agents decide not to proceed with the letting to Frederick Buckler.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Frederick Buckler (greathousefarmwiki.wordpress.com/frederick-buckler/#tenancy-1949)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19530101-1","date":"1953-01-01","year":"1953","location":"Great House Farm","locationType":"other","description":"","narration":"Frederick Buckler makes the last known rent payment around 1953. The family say that after the last known rent payment they paid nothing further to any claimant. Whether and when their occupation became adverse, and what limitation regime applied, remains a legal question to be tested against the title and tenancy documents.","scenes":[],"sources":[],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19550202-1","date":"1955-02-02","year":"1955","location":"Title Office / Great House Farm","locationType":"other","description":"","narration":"On 2 February 1955 the High Court makes a possession order against Frederick Buckler alone, worded for the whole farm. Mary is not a party. On 4 July 1955 possession is taken of everything except the farmhouse and garden, and the family stay on in the house.","scenes":[{"character":"ARCHIVIST","icon":"archive","side":"left","color":"#999","text":"The 1955 record is significant precisely because the order was against Frederick alone while the farmhouse and garden remained occupied. The later chronology must not collapse this into a finding that Mary's own title claim was adjudicated then.","position":{"x":0,"y":0}}],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: The family contend that the order concerned the farmland Frederick had rented, but was worded for the whole farm, treating two parcels as one. Mary, who claimed the house, was not a party."},{"id":"ghf-19590101-1","date":"1959-01-01","year":"1959","location":"Great House Farm, Llandough","locationType":"other","description":"","narration":"In 1959 Mary refuses a tenancy of the farmhouse and garden and asserts ownership. When she tells WGR that documents prove her title, none can be produced: the family papers had been taken from the blanket box in 1950–52.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19610329-1","date":"1961-03-29","year":"1961","location":"HM Land Registry — WA231076 File","locationType":"other","description":"","narration":"A deed dated 29 March 1961 appears on the WA231076 registration file. Its contents are unknown, and it is not yet clear which parcel it concerns.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Land Registry Titles (greathousefarmwiki.wordpress.com/land-registry-titles/#deeds-before-registration)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19621211-1","date":"1962-12-11","year":"1962","location":"Cardiff County Court","locationType":"other","description":"","narration":"On 11 December 1962 Judge Temple Morris QC, in Cardiff County Court, orders possession of the farmhouse and garden, with mesne profits since 1955, against Frederick and Mary Buckler on WGR's claim. The order is not enforced before 1974. The Wiki also flags an open jurisdiction question because the county court's rateable-value limit was £100 in 1962.","scenes":[{"character":"ARCHIVIST","icon":"archive","side":"left","color":"#999","text":"This is a crucial change from the 1955 proceedings: Mary is now expressly named in the possession order concerning the farmhouse and garden. The later chronology therefore has to distinguish the 1962 possession order from the separate question of the documentary root of title.","position":{"x":0,"y":0}}],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19630101-1","date":"1963-01-01","year":"1963","location":"Llandough — Utility Trench","locationType":"other","description":"","narration":"In 1963 three skeletons are reported in utility-trench works near the church. The account comes from a secondary research file; the underlying 1963 record is still being traced. In the same year the National Museum takes in the spur and spearhead found at Church Farm in 1858.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (https://greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Archaeology and Heritage (https://greathousefarmwiki.wordpress.com/archaeology/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19630601-1","date":"1963-06-01","year":"1963","location":"Cardiff County Court","locationType":"other","description":"","narration":"In June 1963 the mesne profits under the 1962 order are partly enforced against Frederick, and committal proceedings follow.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19640101-1","date":"1964-01-01","year":"1964","location":"Family Account","locationType":"other","description":"","narration":"A cousin's account says the eldest son sold 'our land parcel' some time in 1964–67. No document has been found, and the account remains unverified.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19650301-1","date":"1965-03-02","year":"1965","location":"WGR Agents' Office","locationType":"other","description":"","narration":"In January–March 1965 WGR correspondence records that it would not let Frederick the agricultural land. On 2 March WGR’s agents instead offered ‘Mrs Williams’ a weekly tenancy of the farmhouse and garden at £2 a week. The offer was not signed and no rent was paid. The Wiki records Mary as refusing it and continuing to assert that she owned the farmhouse through the 1877 arrangement. The sequence matters because a disputed house parcel was being treated separately in the offer, while the agricultural tenancy and its eastern fields remained a different documentary strand.","scenes":[{"character":"ARCHIVIST","icon":"archive","side":"left","color":"#999","text":"The significance is not that a tenancy existed: the proposed weekly tenancy was never signed. It is another recorded attempt to put Mary's occupation into a permissive tenancy framework.","position":{"x":0,"y":0}}],"sources":["Great House Farm Wiki — Mary Williams, 1965 offer: https://greathousefarmwiki.wordpress.com/mary-williams/#offer-1965","Great House Farm Wiki — 1962 Possession Order / 1965 offer: https://greathousefarmwiki.wordpress.com/1962-possession-order/#offer-1965","Great House Farm Wiki — Western Ground Rents: https://greathousefarmwiki.wordpress.com/western-ground-rents/"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"FAMILY INTERPRETATION: The 1965 offer is one of a series of attempts the family says repeatedly sought to characterise Mary’s occupation as permissive. The document records an offer, not Mary’s acceptance; the original rejection evidence and its legal effect should be kept distinct from the later court’s treatment of the 1974 letters."},{"id":"ghf-19670101-1","date":"1967-01-01","year":"1967","location":"Great House Farm","locationType":"other","description":"","narration":"Frederick Buckler dies aged 56. Mary reverts to her maiden name, Williams, and stays on in the farmhouse.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19680901-1","date":"1968-09-01","year":"1968–69","location":"Great House Farm","locationType":"other","description":"","narration":"Between September 1968 and September 1969 the eldest son's household leaves the farm, according to the family's account.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — The Williams / Buckler Family (greathousefarmwiki.wordpress.com/williams-buckler-family/#rumoured-sale)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19691231-1","date":"1969-12-31","year":"1969","location":"Great House Farm, Llandough","locationType":"other","description":"","narration":"On 31 December 1969 WGR sells to BP Pension Trust Ltd. The conveyance is missing from the Land Registry files released so far.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19700616-1","date":"1970-06-16","year":"1970","location":"Leckwith Road, Llandough","locationType":"other","description":"","narration":"On 16 June 1970 land by Leckwith Road is registered as village green VG41. The wiki's current reconstruction places it in Parcel A; the boundary has still to be confirmed (timeline ref. GHF-E033-VG41).","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Redevelopment and Church View Close (greathousefarmwiki.wordpress.com/redevelopment/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19720725-1","date":"1972-07-25","year":"1972","location":"Planning Office","locationType":"other","description":"","narration":"On 25 July 1972 an earlier planning permission for housing on the site is granted, while Mary Williams is still living in the farmhouse.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Redevelopment and Church View Close (greathousefarmwiki.wordpress.com/redevelopment/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19740101-1","date":"1974-01-01","year":"1974","location":"Great House — Interior","locationType":"other","description":"","narration":"The ground floor of Great House is surveyed in unusual circumstances by H.J. Thomas for the Royal Commission (RCAHMW). Much detail is concealed and the first floor and roof trusses cannot be examined: the house 'remained partially recorded because of problems of access created by an ownership dispute'.","scenes":[],"sources":["GGAT HER PRN 02038s via Archwilio","RCAHMW Inventory Vol IV Part 2","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":["Ground floor surveyed in unusual circumstances in 1974 by H.J.T.","Much detail was concealed — could not examine first floor and roof trusses","House remained partially recorded because of access problems from ownership dispute","Great House plan not published in Inventory due to incompleteness of available information"],"report":[]}},{"id":"ghf-19740415-1","date":"1974-04-15","year":"1974","location":"Great House Farm — Open Day","locationType":"other","description":"","narration":"On 15 April 1974 Mary Williams, then 60, opens the farmhouse to the public 'to show what the nation is losing'. Hundreds come. The Daily Telegraph reports on 16 April that planning permission for about 13 houses has been given to the BP Petroleum Pension Trust, that about 1,000 people have signed a petition, and that Mary says she will refuse to move. The report records her statement that the ownership has been disputed for about 25 years and that her solicitors say she has a valid claim.","scenes":[{"character":"ARCHIVIST","icon":"archive","side":"left","color":"#999","text":"This contemporaneous press evidence matters because Mary's ownership assertion was public before the later 1980s litigation. It is part of the evidence that her position was not simply a later 'notion' that she owned the land.","position":{"x":0,"y":0}}],"sources":["Daily Telegraph, 16 April 1974, 'Open day to save ancient Welsh house', Godfrey Francis (transcript GHF-E090-N03: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n03)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19740703-1","date":"1974-07-03","year":"1974","location":"Court / Great House Farm","locationType":"other","description":"","narration":"On 3 July 1974 BP Pension Trust brings a new possession action. Mary pleads ownership and the Limitation Act 1939. The action is part-heard and never relisted.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: The family contend the action was dropped in the face of press support for Mary. BP later relied on licence letters she never asked for and always disputed."},{"id":"ghf-19740919-1","date":"1974-09-19","year":"1974","location":"Cardiff County Court","locationType":"other","description":"","narration":"On 19 September 1974 the county court judge (Judge Watkin Powell, per the family archive) gives BP leave to enforce the 1962 order, but no warrant is to issue before 31 October. Mary's solicitors appeal because she was given no notice.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19741031-1","date":"1974-10-31","year":"1974","location":"Great House Farm, Llandough","locationType":"other","description":"","narration":"On 31 October 1974 BP Pension Trust Ltd sends Mary letters purporting to licence her to remain at Great House Farm rent-free for life. The family evidence says Mary rejected the premise that BP owned the house and did not agree to the licence. The warrant is withdrawn the same day.","scenes":[{"character":"ARCHIVIST","icon":"archive","side":"left","color":"#999","text":"The later litigation treated the letters as legally effective despite the family's evidence that Mary rejected the premise of the licence. That distinction is central: the chronology must not narrate a unilateral offer as though Mary accepted it.","position":{"x":0,"y":0}}],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19741031-2","date":"1974-10-31","year":"1974","location":"Great House Farm, Llandough","locationType":"other","description":"","narration":"On 31 October 1974, the day the licence letters are sent, the possession warrant is withdrawn and Mary remains in the farmhouse.","scenes":[{"character":"ARCHIVIST","icon":"archive","side":"left","color":"#999","text":"The immediate practical result was continued occupation. The legal significance later attributed to the letters was therefore not the result of Mary signing a tenancy or licence.","position":{"x":0,"y":0}}],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19741119-1","date":"1974-11-19","year":"1970s","location":"Western Mail — Letters","locationType":"other","description":"","narration":"William Rees writes to the Western Mail ('Grievous loss', dated 19/11/7? in the copy held; the year is unclear) that demolishing Great House Farm would erase the site of the Celtic monastery of St Dochdwy. He traces its descent from Tewkesbury Abbey to the Crown at the Dissolution, then to Herbert and to Bute.","scenes":[],"sources":["Western Mail, 'Grievous loss', letter from William Rees, 19/11/7? (transcript GHF-E090-N04: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n04)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19750523-1","date":"1975-05-23","year":"1975","location":"Estate Agent's Office","locationType":"other","description":"","narration":"On 23 May 1975 BP Pension Trust transfers its interest to BP Properties Ltd. Mary maintains that no transfer can defeat the ownership she asserted in court the previous year.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19780101-1","date":"1978-01-01","year":"1978","location":"Llandough Roman Villa (separate site)","locationType":"other","description":"","narration":"GGAT excavates the Llandough Roman Villa (PRN 00768s), south of the church, in 1978–79. This is a separate site, not Great House Farm; earlier versions of this timeline wrongly placed the villa on the farm.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-press-19800417-n05","date":"1980-04-17","year":"1980","location":"Llandough — Neath Guardian report","locationType":"other","description":"","narration":"On 17 April 1980 the Neath Guardian reports on a historical society meeting at which GGAT assistant director Henry Owen-John spoke about recent archaeological excavations at Llandough. The report describes substantial remains of a Roman villa and part of a later medieval house, and praises GGAT’s rescue archaeology. The Wiki identifies the excavation as the separate Llandough Roman villa site, not Great House Farm, so this is contextual newspaper evidence rather than evidence of the farmhouse.","scenes":[],"sources":["GHF-E090-N05 — Neath Guardian, 17 April 1980: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/n05-1980-historical-society-had-notable-year/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N05"],"notes":[],"report":[]}},{"id":"ghf-19800522-1","date":"1980-05-22","year":"1980","location":"House of Commons","locationType":"other","description":"","narration":"On 22 May 1980 Ted Rowlands MP tells the House of Commons that Western Ground Rents, 'the most rapacious ground landlord' in South Wales, has been bought by the BP pension fund. The landlord that sued Frederick in 1955 is now inside the BP group.","scenes":[],"sources":["GHF-E090-N16 — Hansard, 22 May 1980 (https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n16)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19821001-1","date":"1982-10-01","year":"1982","location":"GGAT","locationType":"other","description":"","narration":"On 1 October 1982 GGAT tells the planning authority that occupation may continue north of the church, and asks for 'thorough investigative work prior to the development'.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19821119-1","date":"1982-11-19","year":"1982","location":"Property Transfer","locationType":"other","description":"","narration":"Between 19 and 30 November 1982 BP Pension Trust transfers to BP Properties Ltd, and first registration is applied for (title WA231076); a second application (WA240304) follows on 23 February 1983. Mary Williams is alive and living in the farmhouse throughout. The family contend no inquiry was made of her.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19830223-1","date":"1983-02-23","year":"1983","location":"HM Land Registry — WA240304","locationType":"other","description":"","narration":"On 23 February 1983 BP's solicitors, Linklaters & Paines, apply to register the farmhouse and garden as a separate title, WA240304, and certify that they know of no question or doubt affecting the title. Mary Williams is living in the farmhouse. The Wiki's present question is what the application, notices, requisitions and original register show about the ownership claim then on the record.","scenes":[],"sources":["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#first-registration)","Legal Review, F3 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/#fraud)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"The family's case is that this registration took in the house parcel without disclosing Mary's ownership claim."},{"id":"ghf-19830313-1","date":"1983-03-13","year":"1983","location":"GGAT Warehouse, Swansea","locationType":"other","description":"","narration":"On 13 March 1983 a fire at GGAT's Swansea warehouse destroys the finds from the Llandough Roman villa excavation. The villa is a separate site from Great House Farm.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Press Archive — Newspaper Transcripts (greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n06) — GHF-E090-N06 (South Wales Echo, 18 March 1983)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19830326-1","date":"1983-03-26","year":"1983","location":"Great House Farm / Legal Office","locationType":"other","description":"","narration":"Mary Williams dies at the farmhouse on 26 March 1983, and her son William (Billy) inherits her claim. The farm agreement had been taken from the family's blanket box in 1950–52, so the family's case rests on Mary's statement and their long occupation.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: First registration was applied for while Mary was alive and in occupation, and she died weeks later. Whether she was ever notified is being pursued with HM Land Registry."},{"id":"ghf-19830408-1","date":"1983-04-08","year":"1983","location":"HM Land Registry — WA240304","locationType":"other","description":"","narration":"On 8 and 12 April 1983, two weeks after Mary's death, Linklaters and the Land Registry exchange letters on the farmhouse file, including form D23. On 12 May further letters follow on the main title. What the Registry asked about the family's occupation, and what it was told, is in those letters, which the family is now ordering.","scenes":[],"sources":["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#first-registration)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19840113-1","date":"1984-01-13","year":"1984","location":"HM Land Registry — WA231076","locationType":"other","description":"","narration":"On 13 January 1984 an application on form A3 is made on the main title and a new edition of the register is issued, four months before BP's writ for possession.","scenes":[],"sources":["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19840522-1","date":"1984-05-22","year":"1984","location":"BP Properties Offices","locationType":"other","description":"","narration":"On 22 May 1984 BP Properties issues its writ for possession, relying on the 1974 licence letters. In the same year the library copy of the Bute–Thomas deed is reported missing from Cardiff Library. The family evidence says Mary never accepted the 1974 licence.","scenes":[{"character":"ARCHIVIST","icon":"archive","side":"left","color":"#999","text":"By 1984 the 1974 letters had become the foundation of BP Properties' possession case. The central evidential question is whether a licence rejected by Mary could properly be treated as making her possession permissive, and what material the court actually had when deciding that question.","position":{"x":0,"y":0}}],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19860710-1","date":"1986-07-10","year":"1986","location":"High Court, Cardiff","locationType":"other","description":"","narration":"On 10 July 1986 Mr Justice Hollis gives judgment for BP Properties in the High Court at Cardiff. He holds that the 1974 letters gave Mary a valid licence, so she was not in adverse possession, and suspends the possession order for six months. The Wiki records that the proceedings were framed around possession/adverse possession rather than a completed forensic reconstruction of the underlying documentary root to the farmhouse parcel.","scenes":[{"character":"ARCHIVIST","icon":"archive","side":"left","color":"#999","text":"The 1986 judgment is important because it treated the farm dispute through the possession/licence framework while the Land Registry still contained separate titles. The later 1987 amalgamation did not create that court description retroactively; it followed it while the appeal was pending.","position":{"x":0,"y":0}}],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19860711-1","date":"1986-07-11","year":"1986","location":"Royal Commission (RCAHMW)","locationType":"other","description":"","narration":"From around 1986–87, during the trial and the appeal, the Royal Commission's correspondence between C. N. Johns and Mrs Buckler goes missing. It may have recorded Mary's own account of her title to an independent public body.","scenes":[],"sources":["Legal Review, section 1.3 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/#loss-pattern)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19870202-1","date":"1987-02-02","year":"1987","location":"HM Land Registry","locationType":"other","description":"","narration":"On 2 February 1987, while the appeal from the 1986 judgment is pending, an application is made to amalgamate BP's two titles into one. The separate farmhouse title was therefore being merged before the Court of Appeal delivered its judgment on 31 July 1987.","scenes":[{"character":"ARCHIVIST","icon":"archive","side":"left","color":"#999","text":"This timing matters. The court proceedings and the registered-title structure were moving at the same time: the two titles were still separate when the amalgamation application was made, and the merger occurred before the appeal judgment.","position":{"x":0,"y":0}}],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: The family question why the titles were merged during the appeal; this is being pursued with HM Land Registry."},{"id":"ghf-19870731-1","date":"1987-07-31","year":"1987","location":"Court of Appeal (Civil Division)","locationType":"other","description":"","narration":"On 31 July 1987 the Court of Appeal (Dillon LJ, with Mustill LJ and Sir Edward Eveleigh) dismisses the appeal in BP Properties Ltd v Buckler. It holds that the 1962 action stopped time running and that BP's 1974 letters made Mary's possession permissive whether or not she accepted them. It records that the claimed title documents were not produced. The family's later Wiki reconstruction identifies a further evidential distinction: the 16 April 1974 newspaper report recording Mary's ownership assertion, and the evidence of her rejection of the 1974 licence premise, were not before the Court of Appeal in the form now identified by the family. The chronology therefore must not imply that the Court heard and rejected that complete body of evidence. It also must distinguish the Court's description of the farm from the separate registered titles that were amalgamated during the pending appeal.","scenes":[{"character":"ARCHIVIST","icon":"archive","side":"left","color":"#999","text":"The 1987 judgment is the point at which the permissive-occupation theory becomes decisive. The present evidential question is not simply whether the judges applied that rule correctly, but what evidence they actually had: the chronology identifies contemporaneous evidence of Mary's ownership assertion and rejection of the licence premise that must be compared with the judgment record. Any judicial characterisation of Mary as merely having 'conceived the notion' that she owned the land must likewise be tested against the contemporaneous evidence rather than repeated as an established fact.","position":{"x":0,"y":0}}],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: The family contend the courts decided possession of the whole farm without the documents bearing on the house parcel ever being before them, and that a licence she rejected was used to defeat her claim."},{"id":"ghf-19880303-1","date":"1988-03-03","year":"1988","location":"House of Lords","locationType":"other","description":"","narration":"On 3 March 1988 the House of Lords refuses leave to appeal.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19880429-1","date":"1988-04-29","year":"1988","location":"Great House Farm — First Eviction Attempt","locationType":"other","description":"","narration":"After the House of Lords refusal the family are given 28 days to find somewhere else to live. On 29 April 1988 five bailiffs and about 15 police arrive. Billy blocks the narrow drive with a tractor, locks the doors and bars the windows.","scenes":[],"sources":["'Chainsaw farmer vows to fight on', Andrew Penman, c. 30 April 1988 (transcript GHF-E090-N07: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n07)","South Wales Echo, 29 April 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19880429-2","date":"1988-04-29","year":"1988","location":"Great House Farm — Chainsaw Stand-off","locationType":"other","description":"","narration":"The bailiffs smash the gate lock and break at the doors with poleaxes. When an axe comes through a door with his children behind it, Billy starts a chainsaw and pushes it through the door, and the bailiffs back off. After a four-hour stand-off they withdraw. Branwen leaves with the children, aged two, three and four. BP says it regrets the events; the police say they were there to prevent a breach of the peace, not to help the bailiffs.","scenes":[],"sources":["'Chainsaw farmer vows to fight on', Andrew Penman, c. 30 April 1988 (transcript GHF-E090-N07: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n07)","South Wales Echo, 30 April 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-press-n07","date":"1988-04-29","year":"c. 30 April 1988","location":"Chainsaw farmer vows to fight on — press evidence","locationType":"other","description":"","narration":"Contemporary newspaper report of the 29 April 1988 eviction attempt. It records five bailiffs and around 15 police arriving, William Buckler blocking the drive with a tractor, the farmhouse doors being struck with poleaxes, the chainsaw confrontation, a four-hour stand-off, Branwen leaving with the three children, and William maintaining that the family owned the farm. It also records BP’s account that Mary had been allowed to live there rent-free because of ill health and that proceedings began in May 1984, plus a police statement that officers were present to prevent a breach of the peace.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N07: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/n07-1988-chainsaw-farmer-vows-to-fight-on/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N07"],"notes":[],"report":[]}},{"id":"ghf-press-n15-01","date":"1988-04-29","year":"1988","location":"South Wales Echo — GHF-E090-N15-01","locationType":"other","description":"","narration":"The South Wales Echo’s 29 April 1988 search extract says the dispute had been ‘waged for two generations’, that Mary was reported as having lost three earlier High Court cases while claiming to be the rightful owner, and that BP had agreed in 1974 to let her remain in the farmhouse rent-free. The Wiki flags those statements as the newspaper’s account, not independent proof: no supporting record for the ‘three previous cases’ has yet been surfaced, and the 1974 permission is itself disputed.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-01: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-01-1988-04-29/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-01"],"notes":[],"report":[]}},{"id":"ghf-press-n15-02","date":"1988-04-30","year":"1988","location":"South Wales Echo — GHF-E090-N15-02","locationType":"other","description":"","narration":"The 30 April 1988 South Wales Echo search extract reports that Mr Buckler was refusing to leave Great House Farm for medical attention because he feared the bailiffs would return, and that about a dozen police officers were present during the attempted eviction the previous day. The Wiki records this as next-day press evidence supporting the April stand-off; the extract does not mention the chainsaw.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-02: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-02-1988-04-30/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-02"],"notes":[],"report":[]}},{"id":"ghf-19880503-1","date":"1988-05-03","year":"1988","location":"European Commission of Human Rights","locationType":"other","description":"","narration":"On 3 May 1988 William Buckler applies to the European Commission of Human Rights.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19880512-1","date":"1988-05-12","year":"1988","location":"MP's Office","locationType":"other","description":"","narration":"On 12 May 1988 the South Wales Echo reports that the Cardiff MP Alun Michael has asked the Lord Chancellor to look at the case of the farmer who fought off bailiffs with a chainsaw. Billy warns that someone will be killed.","scenes":[],"sources":["South Wales Echo, 12 May 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-press-n15-03","date":"1988-05-12","year":"1988","location":"South Wales Echo — GHF-E090-N15-03","locationType":"other","description":"","narration":"On 12 May 1988 the South Wales Echo search extract reports that Cardiff MP Alun Michael had asked the Lord Chancellor to look at the case of Bill Buckler, and refers to the earlier chainsaw confrontation. This establishes contemporary press reporting of parliamentary involvement; the extract contains no reply or outcome from the Lord Chancellor.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-03: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-03-1988-05-12/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-03"],"notes":[],"report":[]}},{"id":"ghf-19880729-1","date":"1988-07-29","year":"1988","location":"Cadw Offices","locationType":"other","description":"","narration":"On 29 July 1988 Cadw inspects and photographs the farmhouse and barn while considering it for listing. Only those two photographs survive today: Cadw has no file, no notes and no record of who decided, and in 2026 it gave three different explanations of what its code meant.","scenes":[],"sources":["Cadw — Forensic Critique v8.0.0 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/cadw-forensic-critique-v8-0-0/)","Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19881130-1","date":"1988-11-30","year":"1988","location":"Great House Farm — Forced Entry","locationType":"other","description":"","narration":"BP obtains possession at the end of November 1988; the press places the forced entry on Wednesday 30 November. Within hours, the family say, demolition begins: half the roof is already off one of the outbuildings. Eight other people living at the farm are made homeless with the family.","scenes":[],"sources":["South Wales Echo, 30 November 1988, 'Angry scenes as farmer evicted' (transcript GHF-E090-N14: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n14)","South Wales Echo, 30 November 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)","South Wales Echo, 3 December 1988, 'Billy's unhappy family' (transcript GHF-E090-N09: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n09)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19881130-2","date":"1988-11-30","year":"1988","location":"Great House Farm — Final Eviction","locationType":"other","description":"","narration":"Billy is taken to Llandough Hospital after the eviction. He is later charged with assaulting two bailiffs, criminal damage, and wanton or furious driving.","scenes":[],"sources":["South Wales Echo, 3 December 1988 (transcript GHF-E090-N08: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n08)","South Wales Echo, 3 December 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-press-n14","date":"1988-11-30","year":"c. 30 November 1988","location":"Angry scenes as farmer evicted — press evidence","locationType":"other","description":"","narration":"South Wales Echo front page evidence. The legible headlines are ‘Angry scenes as farmer evicted’, ‘A bitter feud over rights that lasted 33 years’, and ‘Action on farm’. The body text and even the masthead date are not legible in the copy currently held, so this event records only what can actually be read. The date remains approximate and must be confirmed from a clear archive copy.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N14: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/n14-1988-angry-scenes-as-farmer-evicted/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N14"],"notes":[],"report":[]}},{"id":"ghf-press-n15-04","date":"1988-11-30","year":"1988","location":"South Wales Echo — GHF-E090-N15-04","locationType":"other","description":"","narration":"On 30 November 1988 the South Wales Echo search extract reports that people who had forced their way into Great House Farm had already taken half the roof off an outbuilding, while Branwen Buckler feared BP would flatten the farmhouse. The sentence is cut off, but the report supports the dating of forced entry and same-day demolition of an outbuilding.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-04: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-04-1988-11-30/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-04"],"notes":[],"report":[]}},{"id":"ghf-19881201-1","date":"1988-12-01","year":"1988","location":"Llandough Hospital","locationType":"other","description":"","narration":"Billy Buckler lies injured in Llandough Hospital from the eviction of 30 November. Branwen and the three young children have nowhere to go. The family say Mary's lifetime of possessions, photographs, heirlooms and legal documents were left in the house or scattered in the road.","scenes":[],"sources":["Press Archive transcript GHF-E090-N08 (South Wales Echo, 3 December 1988): https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n08","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19881202-1","date":"1988-12-02","year":"1988","location":"Court","locationType":"other","description":"","narration":"A High Court judge grants an interim injunction that the farmhouse and its contents must not be touched. On 2 December Mr Justice Anthony Evans allows Branwen to collect belongings from the house if BP's solicitors agree. Cadw considers emergency 'spot-listing' and sends an inspector.","scenes":[],"sources":["South Wales Echo, 3 December 1988, 'History fight to save farm', Peter Bibby (transcript GHF-E090-N08: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n08)","South Wales Echo, 2 December 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-press-n15-05","date":"1988-12-02","year":"1988","location":"South Wales Echo — GHF-E090-N15-05","locationType":"other","description":"","narration":"The 2 December 1988 South Wales Echo search extract reports a High Court summons involving BP and says Mr Justice Anthony Evans allowed Mrs Buckler to enter the house and collect belongings provided BP’s solicitors agreed. It also refers to a family petition, but the extract does not show its subject or the full terms of the order.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-05: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-05-1988-12-02/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-05"],"notes":[],"report":[]}},{"id":"ghf-19881203-1","date":"1988-12-03","year":"1988","location":"Cadw — Listing Assessment","locationType":"other","description":"","narration":"Over the weekend of 3 to 5 December 1988 Cadw assesses the farmhouse for emergency spot-listing in about 48 hours, with no access to the interior. Publicly it says it is 'considering' listing, although in July it had coded the house just below the bar.","scenes":[],"sources":["Cadw — Forensic Critique v8.0.0, Part VI (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/cadw-forensic-critique-v8-0-0/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-press-n08","date":"1988-12-03","year":"3 December 1988","location":"History fight to save farm — press evidence","locationType":"other","description":"","narration":"South Wales Echo report on the aftermath of the 30 November possession. It says Cadw was considering emergency ‘spot-listing’, that an inspector would visit, that the family described a 33-year legal battle and claimed the bailiffs began demolition within hours, and that BP intended to demolish the farmhouse and outbuildings and seek planning permission for new homes on the 10-acre site. It also reports the anticipated 5 December High Court hearing.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N08: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/n08-1988-history-fight-to-save-farm-1988/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N08"],"notes":[],"report":[]}},{"id":"ghf-press-n09","date":"1988-12-03","year":"3 December 1988","location":"Billy’s unhappy family — press evidence","locationType":"other","description":"","narration":"South Wales Echo reports that eight other people were living at Great House Farm when the Buckler family were evicted, including people whose rent was reportedly paid by the Vale of Glamorgan Borough Council. It describes a semi-communal group whose stays had become permanent and records their homelessness following the eviction. It also reports comments from Chris Thompson and Karen Griffiths about the impact of the legal battle.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N09: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/n09-1988-billys-unhappy-family-1988/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N09"],"notes":[],"report":[]}},{"id":"ghf-press-n15-06","date":"1988-12-03","year":"1988","location":"South Wales Echo — GHF-E090-N15-06","locationType":"other","description":"","narration":"The 3 December 1988 South Wales Echo search extract reports that Bill Buckler had been taken from his hospital bed to face charges of assault on two bailiffs after the eviction, and describes the dispute as a 33-year wrangle. The extract gives his age as 40, whereas another same-day Echo report gives 39; the Wiki records the discrepancy rather than choosing between them. A charge is not a finding of guilt.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-06: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-06-1988-12-03/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-06"],"notes":[],"report":[]}},{"id":"ghf-19881205-1","date":"1988-12-05","year":"1988","location":"Cardiff — Injunction Hearing","locationType":"other","description":"","narration":"On Monday 5 December 1988 Judge Norman Francis dismisses the Bucklers' application to keep the injunction until the European Commission of Human Rights has considered their case. Their solicitor, Colin Jongman, says there are no more steps to take. Cadw says the house is not of sufficient architectural merit to list.","scenes":[],"sources":["Western Mail, 6 December 1988, 'Farmer fails in final eviction hearing' (transcript GHF-E090-N10: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n10)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19881206-1","date":"1988-12-06","year":"1988","location":"Great House Farm — Demolition","locationType":"other","description":"","narration":"The outbuildings are demolished from 30 November. Just after 4am on 6 December 1988 a twenty-strong team with bulldozers moves in, and by breakfast no building is left standing. Branwen and the three children watch their home flattened.","scenes":[],"sources":["'Tears flow as 800 year-old farm house is razed at last', c. 7 December 1988 (transcript GHF-E090-N11: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n11)","South Wales Echo, 6 December 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: Demolition destroyed the house before its fabric could be fully recorded: the Royal Commission's survey was never completed, and features were lost in the rubble."},{"id":"ghf-press-n10","date":"1988-12-06","year":"6 December 1988","location":"Farmer fails in final eviction hearing — press evidence","locationType":"other","description":"","narration":"The Western Mail reports that the family’s final attempt to restrain BP from destroying the farmhouse failed after a hearing in chambers. The article says the property was a reputedly 800-year-old, 10-acre site overlooking Cardiff Bay; the Bucklers hoped to keep it pending a European case; the solicitor said there were no more steps to stop demolition; and Cadw said the house was not of sufficient architectural merit and the land was not of sufficient archaeological interest. These are reported statements and decisions, not an independent finding by this timeline.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N10: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/n10-1988-farmer-fails-in-final-eviction-hearing-1988/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N10"],"notes":[],"report":[]}},{"id":"ghf-press-n11","date":"1988-12-06","year":"c. 7 December 1988","location":"Tears flow as 800 year-old farm house is razed at last — press evidence","locationType":"other","description":"","narration":"The demolition report says a twenty-strong team with bulldozers moved in just after 4am and that by breakfast no building remained on the ten-acre site. It records Branwen and the three children watching the demolition and says possession had been granted to BP the day before after the High Court rejected the effort to extend an injunction. The article describes the 35-year ownership battle and reports that William had admitted not paying rent for 35 years while claiming rights to the house. The latter is a newspaper report of his position and the proceedings, not a substitute for the court record.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N11: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/n11-1988-tears-flow-as-farm-house-razed-1988/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N11"],"notes":[],"report":[]}},{"id":"ghf-press-n15-07","date":"1988-12-06","year":"1988","location":"South Wales Echo — GHF-E090-N15-07","locationType":"other","description":"","narration":"The 6 December 1988 South Wales Echo search extract says the family had been battling for more than 30 years to prove ownership, that the fight ended in the High Court in Cardiff on the previous afternoon, and that BP Properties acted within hours. The Wiki treats this as contemporary press evidence for the 5 December hearing followed by the early-hours demolition on 6 December, while noting that the extract’s court description differs from another report.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-07: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-07-1988-12-06/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-07"],"notes":[],"report":[]}},{"id":"ghf-press-n15-08","date":"1988-12-07","year":"1988","location":"South Wales Echo — GHF-E090-N15-08","locationType":"other","description":"","narration":"On 7 December 1988 the South Wales Echo reports a Vale of Glamorgan councillor, who was also a BP pensioner, calling the decision to flatten the buildings ‘disgusting’ and saying he would write in protest. The report records contemporary local political reaction; it is not evidence of title.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-08: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-08-1988-12-07/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-08"],"notes":[],"report":[]}},{"id":"ghf-19881208-1","date":"1988-12-08","year":"1988","location":"Community Meeting","locationType":"other","description":"","narration":"A Vale of Glamorgan councillor, himself a BP pensioner, calls the demolition 'disgusting'. On 8 December Llandough villagers meet their councillors in anger. The family also recall the council's planning chief saying the cleared site looked like a battleground.","scenes":[],"sources":["South Wales Echo, 7 and 9 December 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)","1988: Possession and Demolition (https://greathousefarmwiki.wordpress.com/demolition-1988/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19881209-1","date":"1988-12-09","year":"1988","location":"Llandough Hospital / Magistrates Court","locationType":"other","description":"","narration":"Police take Billy Buckler from his hospital bed to face charges of assaulting two bailiffs. On 9 December magistrates free him on bail, with conditions keeping him away from the site.","scenes":[],"sources":["South Wales Echo, 3 and 10 December 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)","January 1989 (transcript GHF-E090-N12: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n12)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-press-n15-09","date":"1988-12-09","year":"1988","location":"South Wales Echo — GHF-E090-N15-09","locationType":"other","description":"","narration":"The 9 December 1988 South Wales Echo search extract reports a bid to stop BP profiting from the demolition and says a small group of Llandough villagers met local councillors the previous night to express anger. The extract does not say what action was proposed or whether any succeeded.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-09: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-09-1988-12-09/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-09"],"notes":[],"report":[]}},{"id":"ghf-press-n15-10","date":"1988-12-10","year":"1988","location":"South Wales Echo — GHF-E090-N15-10","locationType":"other","description":"","narration":"The 10 December 1988 South Wales Echo search extract reports that Mr Buckler was freed on bail by magistrates on 9 December and refers to the farm being demolished that week. The extract does not show the charges, court conditions or other outcome details.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-10: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-10-1988-12-10/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-10"],"notes":[],"report":[]}},{"id":"ghf-19881211-1","date":"1988-12-11","year":"1988","location":"Great House Farm — HER Record","locationType":"archive","description":"","narration":"The Glamorgan-Gwent Historic Environment Record (PRN 02038s) independently confirms that Great House Farm was suddenly and completely demolished by B.P. Properties Ltd. on 6th December 1988 amid considerable local controversy. The record documents the 800-year history of the site, including the medieval finds, Vaughan family tenure, Bute Estate ownership, and the disputed demolition. The HER cross-references the RCAHMW Inventory Vol IV Part 2 and provides official archaeological corroboration of the family account.","scenes":[],"sources":["GGAT HER PRN 02038s via Archwilio (https://archwilio.org.uk/her/chi3/report/page.php?watprn=GGAT02038s)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":["HER PRN 02038s: suddenly and completely demolished by B.P. Properties Ltd. on 6th December 1988","Demolition occurred amid considerable local controversy","Cross-references RCAHMW Inventory Vol IV Part 2","Official record compiled 21 Aug 1991, last updated 13 Oct 2023"],"report":[]}},{"id":"ghf-19881212-1","date":"1988-12-12","year":"1988","location":"Great House Farm — Demolition Rubble","locationType":"other","description":"","narration":"In December 1988 R.F. Suggett of the Royal Commission examines the rubble. He records a fireplace jamb, an ogee-stopped beam with torus (a form uncommon in Glamorgan), and the loss of the carved dressed-stone capital kept by the front door, presumably from the old church.","scenes":[],"sources":["GGAT HER PRN 02038s — Supplementary Notes (R.F. Sugget, December 1988)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":["Fireplace jamb since found in rubble after demolition","Carved dressed-stone capital by front door — presumably from old church — lost during demolition","Ogee-stopped beam with torus found in rubble — uncommon in Glamorgan (Inventory Map 50)","Report by R.F. Sugget, December 1988"],"report":[]}},{"id":"ghf-press-n15-11","date":"1988-12-13","year":"1988","location":"South Wales Echo — GHF-E090-N15-11","locationType":"other","description":"","narration":"The 13 December 1988 South Wales Echo search extract records Bill Buckler saying he had only the clothes he stood up in after his eviction, and reports that BP demolished the building about a week later. It is contemporary evidence of his reported loss of possessions and the family’s account of the timing; it is not an inventory.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-11: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-11-1988-12-13/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-11"],"notes":[],"report":[]}},{"id":"ghf-press-n15-12","date":"1988-12-21","year":"1988","location":"South Wales Echo — GHF-E090-N15-12","locationType":"other","description":"","narration":"A reader’s letter published on 21 December 1988 refers to the Echo’s 6 December report headed ‘Bulldozed Before Breakfast’ and includes a photograph caption identifying Branwen Buckler with the children beside the remains of the farmhouse. The letter is opinion, but it provides an additional contemporary lead to the 6 December reporting and photograph.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-12: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-12-1988-12-21/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-12"],"notes":[],"report":[]}},{"id":"ghf-press-n15-13","date":"1989-01-06","year":"1989","location":"South Wales Echo — GHF-E090-N15-13","locationType":"other","description":"","narration":"On 6 January 1989 the South Wales Echo reports that Bill Buckler’s bail conditions were changed in relation to charges of assault, criminal damage and wanton or furious driving. It says his Llandough house had been demolished late the previous year. The extract does not disclose the new conditions or outcome.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-13: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-13-1989-01-06/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-13"],"notes":[],"report":[]}},{"id":"ghf-19890115-1","date":"1989-01-15","year":"1989","location":"Court","locationType":"other","description":"","narration":"In January 1989 the Crown Prosecution Service withdraws, as out of time, a summons alleging threatening behaviour on 29 April 1988. The charges of assault and wanton and furious driving from November remain, and Billy is ordered not to go within half a mile of the site.","scenes":[],"sources":["'Charge against evicted farmer dropped', January 1989 (transcript GHF-E090-N12: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n12)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19890320-1","date":"1989-03-20","year":"1989","location":"Demolition Site","locationType":"other","description":"","narration":"On 20 March 1989 lorries move onto the site at 7.30am to clear the rubble; the operation takes several days.","scenes":[],"sources":["South Wales Echo, 20 March 1989 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-press-n15-14","date":"1989-03-20","year":"1989","location":"South Wales Echo — GHF-E090-N15-14","locationType":"other","description":"","narration":"The 20 March 1989 South Wales Echo search extract reports lorries moving onto the site at 7.30am for an operation likely to take several days, in the context of the long ownership battle. The text is too short to establish whether this was further demolition, rubble clearance or removal of remaining structures. The Wiki therefore marks the exact activity as unresolved.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-14: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-14-1989-03-20/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-14"],"notes":[],"report":[]}},{"id":"ghf-19890323-1","date":"1989-03-23","year":"1989","location":"Court","locationType":"other","description":"","narration":"On 23 March 1989 Billy pleads guilty to the remaining charges and is freed. He vows to fight on over the loss of his home and more than 70 acres of land.","scenes":[],"sources":["South Wales Echo, 23 and 24 March 1989 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-press-n15-15","date":"1989-03-23","year":"1989","location":"South Wales Echo — GHF-E090-N15-15","locationType":"other","description":"","narration":"On 23 March 1989 the South Wales Echo reports that an evicted farmer who lost his home at Great House Farm had ‘today admitted two’ matters and was freed. The extract cuts off before identifying what was admitted, the court outcome or the precise terms, so the Wiki does not infer those details.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-15: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-15-1989-03-23/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-15"],"notes":[],"report":[]}},{"id":"ghf-press-n15-16","date":"1989-03-24","year":"1989","location":"South Wales Echo — GHF-E090-N15-16","locationType":"other","description":"","narration":"The 24 March 1989 South Wales Echo search extract reports Bill Buckler saying he would continue his fight over the loss of his family home and ‘more than 70 acres of land’. The acreage is a reported claim and is not used by the Wiki to establish the extent of either parcel.","scenes":[],"sources":["Great House Farm Wiki — GHF-E090-N15-16: https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e090-n15-south-wales-echo-search-extracts/ghf-e090-n15-16-1989-03-24/","Great House Farm Wiki — Press Articles Index: https://greathousefarmwiki.wordpress.com/evidence-library/press-articles-index/"],"attachments":{"gallery":[],"legal":[],"news":["GHF-E090-N15-16"],"notes":[],"report":[]}},{"id":"ghf-19890325-1","date":"1989-03-25","year":"1989","location":"Temporary Accommodation","locationType":"other","description":"","narration":"The family live with Billy's sister in Penarth. Billy plans to convert an old bus into a home, and says about £30,000 of his possessions were taken from the site after the demolition.","scenes":[],"sources":["South Wales Echo, 1989, 'From farm to a bus', Peter Collins (transcript GHF-E090-N13: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n13)","Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19890414-1","date":"1989-04-14","year":"1989","location":"European Commission of Human Rights","locationType":"other","description":"","narration":"On 14 April 1989 the European Commission accepts that the possession order interfered with William Buckler's home, but holds it lawful and justified, and declares the application inadmissible.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19891010-1","date":"1989-10-10","year":"1989","location":"HM Land Registry — WA513690","locationType":"other","description":"","narration":"On 10 October 1989 BP sells Oakview (title WA513690). How this land relates to the two parcels is unclear.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Land Registry Titles (greathousefarmwiki.wordpress.com/land-registry-titles/#later-dealings)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19891107-1","date":"1989-11-07","year":"1989","location":"Vale of Glamorgan Planning","locationType":"other","description":"","narration":"In October–November 1989 BP lodges outline application 89/01396/OUT for housing. The planning report records that buildings the Local Plan said should be kept had already been demolished. Outline permission follows on 13 March 1990, with 18 conditions.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19891108-1","date":"1989-11-08","year":"1989","location":"GGAT — Consultee Report","locationType":"other","description":"","narration":"In its report on BP's outline application, GGAT advises that the application should not be decided without an archaeological assessment, specifies the trenching, prices the work at £2,000 over two weeks, and discloses negotiations with BP's agents. BP then commissions GGAT to do the work. The same report describes the farmhouse as having been listed as a 'county treasure'.","scenes":[],"sources":["GGAT — Forensic Review v4.0.3 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/ggat-forensic-review-and-evidence-schedule-v4-0-3/)","Redevelopment (https://greathousefarmwiki.wordpress.com/redevelopment/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19900208-1","date":"1990-02-08","year":"1990","location":"Vale of Glamorgan Planning","locationType":"other","description":"","narration":"On 8 February 1990 GGAT sends further comments on the outline application (Appendix B). They are missing from the planning file.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Redevelopment and Church View Close (greathousefarmwiki.wordpress.com/redevelopment/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19900313-1","date":"1990-03-13","year":"1990","location":"Vale of Glamorgan Planning","locationType":"other","description":"","narration":"On 13 March 1990 outline permission is granted with 18 conditions, including archaeological access, evaluation and mitigation. The officer's report had noted that the Local Plan said the farm buildings should be retained, but 'they were unfortunately demolished a little while ago'. No building preservation notice had ever been served.","scenes":[],"sources":["Redevelopment (https://greathousefarmwiki.wordpress.com/redevelopment/)","Legal Review, section 4.4 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/#criticism-register)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19900801-1","date":"1990-08-01","year":"1990","location":"GGAT Field Evaluation","locationType":"other","description":"","narration":"In August 1990 GGAT digs eight machine trenches for BP. The eastern area 'could not be investigated', yet is zoned low potential. Early-medieval burials are found.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19901015-1","date":"1990-10-15","year":"1990","location":"Vale of Glamorgan Planning","locationType":"other","description":"","narration":"On 15 October 1990 the council records condition 17, the archaeological evaluation, as complied with, on the strength of GGAT's eight-trench evaluation of August.","scenes":[],"sources":["Redevelopment (https://greathousefarmwiki.wordpress.com/redevelopment/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19910821-1","date":"1991-08-21","year":"1991","location":"Glamorgan-Gwent HER","locationType":"archive","description":"","narration":"The Glamorgan-Gwent Historic Environment Record compiles its official record of Great House Farm (PRN 02038s), synthesising archaeological assessments, the RCAHMW Inventory, and the supplementary notes of R.F. Sugget. This is followed by the first related archaeological event — an assessment of land at Great House Farm in 1990 (GGATE000877). The HER record will become the definitive archaeological account of the site, independently corroborating the demolition and documenting eight centuries of history.","scenes":[],"sources":["GGAT HER PRN 02038s — Compiled 21-08-1991","GGATE000877: Great House Farm Archaeological Assessment (1990)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":["HER PRN 02038s compiled 21 Aug 1991, last updated 13 Oct 2023","Seven related archaeological events: 1990 (two events), 1994, 2006, 2010 (two events), 2013","Events include assessments, excavations and evaluations of Great House Farm and environs"],"report":[]}},{"id":"ghf-19920514-1","date":"1992-05-14","year":"1992","location":"Vale of Glamorgan Planning","locationType":"other","description":"","narration":"On 14 May 1992 Ideal Homes Wales applies for approval of 20 detached houses on the farm site (92/00671/RES), more than a year before BP transfers the land to it.","scenes":[],"sources":["Redevelopment (https://greathousefarmwiki.wordpress.com/redevelopment/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19920515-1","date":"1992-05-15","year":"1992","location":"Llandough","locationType":"other","description":"","narration":"William (Billy) Buckler dies at Llandough Hospital on 15 May 1992 after a heart attack. He is buried at Michaelston-le-Pit after a funeral at Bethesda Chapel, Dinas Powys. He had been born in the farmhouse and defended it to the end.","scenes":[],"sources":["The Williams / Buckler Family (https://greathousefarmwiki.wordpress.com/williams-buckler-family/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19920727-1","date":"1992-07-27","year":"1992","location":"GGAT","locationType":"other","description":"","narration":"On 27 July 1992 GGAT warns the council that the 1990 assessment showed significant archaeological deposits, including medieval and possibly earlier material and human bone, and urges mitigation. Page 2 of the letter is missing from the file.","scenes":[],"sources":["GGAT — Forensic Review v4.0.3, Test 9 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/ggat-forensic-review-and-evidence-schedule-v4-0-3/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19920903-1","date":"1992-09-03","year":"1992","location":"Vale of Glamorgan Planning","locationType":"other","description":"","narration":"On 3 September 1992, 38 days after GGAT's warning, the reserved matters for 20 houses are approved with no new archaeological condition. GGAT then records no act on the site for 466 days.","scenes":[],"sources":["Redevelopment (https://greathousefarmwiki.wordpress.com/redevelopment/)","GGAT — Forensic Review v4.0.3 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/ggat-forensic-review-and-evidence-schedule-v4-0-3/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19931203-1","date":"1993-12-03","year":"1993","location":"Former Farm Site","locationType":"other","description":"","narration":"On 3 December 1993 BP transfers the site to Ideal Homes, and groundworks begin before the archaeological condition has been met.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19931213-1","date":"1993-12-13","year":"1993","location":"GGAT / Vale of Glamorgan","locationType":"other","description":"","narration":"On 13 December 1993, with groundworks already under way, GGAT recommends urgent consideration of a breach-of-condition notice, saying condition 18 has not been fulfilled. The developer relies on counsel's opinion that it has been discharged, and the council accepts that, later telling the MP it was 'a difference of opinion'.","scenes":[],"sources":["Redevelopment (https://greathousefarmwiki.wordpress.com/redevelopment/)","Legal Review, section 4.4 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/#criticism-register)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19940421-1","date":"1994-04-21","year":"1994","location":"Cemetery Excavation, Former Farm Site","locationType":"other","description":"","narration":"From 21 April to at least 3 May 1994 the Home Office licence to remove human remains has lapsed while work goes on. On 28 April GGAT's officer orders the excavation contractor to do 'no further work' until a brief is approved; under what authority is still unidentified. Removing remains without a licence was an offence under the Burial Act 1857.","scenes":[],"sources":["GGAT — Forensic Review v4.0.3, Tests 8 and 10 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/ggat-forensic-review-and-evidence-schedule-v4-0-3/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19940504-1","date":"1994-05-04","year":"1994","location":"Cemetery Excavation, Former Farm Site","locationType":"other","description":"","narration":"In 1994, after a Home Office licence (21 March) and agreement to 'preservation by record', the Cotswold Archaeological Trust excavates an early-medieval cemetery on the former farm site. Burials are found in the zone GGAT's 1990 evaluation had called low potential, many just below the topsoil. Published totals reach 1,026 burials, the largest early-medieval burial population then recovered from Wales.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"CHALLENGE: The site was developed into 20 houses, permanently erasing the physical evidence. No public inquiry was held into the demolition or the family's eviction."},{"id":"ghf-19940728-1","date":"1994-07-28","year":"1994","location":"National Museum of Wales","locationType":"other","description":"","narration":"On 28 July 1994 Ideal Homes Wales, as landowner, donates the excavated human remains and finds from 'Great House Farm, Llandough' to the National Museum (accession 95.56H). Ownership of finds follows ownership of the land.","scenes":[],"sources":["Archaeology and Heritage (https://greathousefarmwiki.wordpress.com/archaeology/)","Legal Review, section 2.3 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/#land)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19941110-1","date":"1994-11-10","year":"1994","location":"Woodland — WA735527","locationType":"other","description":"","narration":"On 10 November 1994 the woodland, title WA735527, is transferred to Forest of Cardiff. The wiki places the woodland in Parcel A.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Woodland (greathousefarmwiki.wordpress.com/woodland/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-19950628-1","date":"1995-06-28","year":"1995–96","location":"HM Land Registry — WA231076 File","locationType":"other","description":"","narration":"Rights are granted to South Wales Electricity, and there is correspondence with Persimmon. This is the last dealing on the registration file.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Land Registry Titles (greathousefarmwiki.wordpress.com/land-registry-titles/#later-dealings)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20050101-1","date":"2005-01-01","year":"2005","location":"Medieval Archaeology","locationType":"other","description":"","narration":"The 1994 excavation is published in Medieval Archaeology: 1,026 burials in all, 814 of them articulated. The publication tells the story of the cemetery; it does not tell the story of the family whose home stood beside it.","scenes":[],"sources":["Archaeology and Heritage (https://greathousefarmwiki.wordpress.com/archaeology/)","Holbrook and Thomas, Medieval Archaeology 49 (2005)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20051222-1","date":"2005-12-22","year":"2005","location":"Woodland — WA735527","locationType":"other","description":"","narration":"On 22 December 2005 part of the woodland title is divided off.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Woodland (greathousefarmwiki.wordpress.com/woodland/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20190320-1","date":"2019-03-20","year":"2019","location":"RCAHMW National Archive","locationType":"other","description":"","narration":"On 20 March 2019 GGAT's 1990 assessment is accessioned to the national record, about 28 years after it was written.","scenes":[],"sources":["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20251117-1","date":"2025-11-17","year":"2025","location":"Royal Commission (RCAHMW)","locationType":"other","description":"","narration":"In November 2025 the family's records campaign begins. The Royal Commission says it cannot advise on a legal case but holds archives on the site; Llandough Community Council says it cannot help; the Vale of Glamorgan refers the family's request about BP v Buckler to its Information Governance team.","scenes":[],"sources":["Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260123-1","date":"2026-01-23","year":"2026","location":"Cadw / Welsh Government","locationType":"other","description":"","narration":"On 23 January 2026 the family's records request to Cadw bounces: cadw@gov.wales and foi@gov.wales both return 'address not found'. Cadw's published addresses will fail to deliver the family's mail at least eight times this year. On 29 January the family apply to HM Land Registry to record the interest left out at first registration.","scenes":[],"sources":["Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260323-1","date":"2026-03-23","year":"2026","location":"HM Land Registry","locationType":"other","description":"","narration":"On 23 March 2026 HM Land Registry sets out the registration history of Tŷ Mawr Farm and says there is 'no evidence of a mistake in the register'. It treats the farm as one holding and does not explain the root of title to the house parcel.","scenes":[],"sources":["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#hmlr-2026)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260419-1","date":"2026-04-19","year":"2026","location":"HM Land Registry","locationType":"other","description":"","narration":"On 19 April 2026 the stage-one complaint is rejected: the Land Registry says it cannot look behind the 1987 judgment. On 25 May the stage-two decision says the title has been 'registered correctly'. Both decisions rest on a judgment that decided possession, not on any deed to the farmhouse.","scenes":[],"sources":["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#hmlr-2026)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260521-1","date":"2026-05-21","year":"2026","location":"Cadw Listed Buildings","locationType":"other","description":"","narration":"On 21 May 2026 Cadw releases two photographs from 29 July 1988, coded 'YYY', which it says means 'marginally below the bar'. It has no other electronic record, says the paper files are 'quite likely' destroyed, and promises a search. On 2 and 10 July its review says the file has 'most likely' been destroyed, though no destruction record exists.","scenes":[],"sources":["Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)","Cadw — Forensic Critique v8.0.0 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/cadw-forensic-critique-v8-0-0/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260602-1","date":"2026-06-02","year":"2026","location":"HM Land Registry","locationType":"other","description":"","narration":"On 2 and 3 June 2026 the family ask to inspect the original Land Registry files and ask that nothing be destroyed while the matter is open. The request goes unanswered in substance for months, and several Registry addresses bounce.","scenes":[],"sources":["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#hmlr-2026)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260730-1","date":"2026-07-30","year":"2026","location":"HM Land Registry","locationType":"other","description":"","narration":"On 30 July 2026, six months after the first request, the Land Registry releases a schedule of the 43 documents on the first-registration files. The 31 December 1969 conveyance, recited as BP's root of title, is not among them, nor is the 1971 abstract.","scenes":[],"sources":["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#deeds-before-registration)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260825-1","date":"2026-08-25","year":"2026","location":"Amgueddfa Cymru — Museum Wales","locationType":"other","description":"","narration":"On 25 August 2026 the Museum refuses the family's request as 'not held', while saying in the same letter that its searches found records of other discoveries at Great House Farm and Church Farm, which it withholds as 'not in scope'. Those records will be released only on 5 October, after two further request numbers.","scenes":[],"sources":["Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260908-1","date":"2026-09-08","year":"2026","location":"Glamorgan Archives","locationType":"other","description":"","narration":"On 8 September 2026 Glamorgan Archives reply that they hold no deeds for the 1877 Daniel Thomas transaction, but point to Bute X.6(12), the Bute trustees' 1877 abstract of payments and receipts, now at Cardiff Library. A capital payment from Daniel Thomas in that book would prove the sale.","scenes":[],"sources":["The 1877 Agreement (https://greathousefarmwiki.wordpress.com/1877-agreement/#glamorgan-2026-4097b)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260917-1","date":"2026-09-17","year":"2026","location":"Cadw / Welsh Government","locationType":"other","description":"","narration":"On 17 September 2026 the family serve a formal stage-one complaint on Cadw over its 1988 listing decision and the loss of its file. Cadw's own address blocks it; it is re-served on the Chief Inspector on 20 September. On 21 September a Land Registry support agent tells the family the title was 'closed in 2005', contradicting the Registry's own history.","scenes":[],"sources":["Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)","Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#hmlr-2026)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260922-1","date":"2026-09-22","year":"2026","location":"Great House Farm Wiki","locationType":"other","description":"","narration":"On 22 September 2026 the family launch the Great House Farm Wiki, a public evidence archive. Every document is shown first, labelled by type, then explained, so that anyone can follow the story on the record. Nothing is kept secret.","scenes":[],"sources":["Great House Farm Wiki (https://greathousefarmwiki.wordpress.com/)","Where Things Stand (https://greathousefarmwiki.wordpress.com/where-things-stand/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260923-1","date":"2026-09-23","year":"2026","location":"The National Archives","locationType":"other","description":"","narration":"On 23 September 2026 The National Archives identifies the House of Lords judicial papers in BP Properties Limited v Buckler (YHL/PO/JO/10/11/2536), released on its catalogue only in May 2026. Earlier searches had found nothing.","scenes":[],"sources":["Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260925-1","date":"2026-09-25","year":"2026","location":"Forest of Cardiff — Woodland","locationType":"other","description":"","narration":"On 25 September 2026 the Forest of Cardiff, which holds the woodland title WA735527, offers the family a route to ownership. On 27 September the family decline the terms. No price is recorded for the charity's 1994 acquisition.","scenes":[],"sources":["Woodland (https://greathousefarmwiki.wordpress.com/woodland/)","Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260927-1","date":"2026-09-27","year":"2026","location":"Heneb / HM Land Registry","locationType":"other","description":"","narration":"On 27 September 2026 the family lodge a formal complaint with Heneb over GGAT's role from 1982 to 1995 and the heritage record, and refer HM Land Registry to the Independent Complaints Reviewer. On 28 September a preservation notice goes to eleven public bodies. Heneb appoints an investigating officer on 29 September; the Reviewer opens case ICR/090/26.","scenes":[],"sources":["GGAT — Forensic Review v4.0.3 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/ggat-forensic-review-and-evidence-schedule-v4-0-3/)","Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20260929-1","date":"2026-09-29","year":"2026","location":"Cadw / RCAHMW","locationType":"other","description":"","narration":"On 29 September 2026 Cadw's complaints investigation begins. The same day the Royal Commission answers four requests together (RC26-0375). Its archive holds a 1974 newspaper report and an older note of the story of a soldier in armour found under the dining-room floor, so the story was on record long before the demolition.","scenes":[],"sources":["Archaeology and Heritage (https://greathousefarmwiki.wordpress.com/archaeology/)","Where Things Stand (https://greathousefarmwiki.wordpress.com/where-things-stand/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20261003-1","date":"2026-10-03","year":"2026","location":"Great House Farm Wiki — Press Archive","locationType":"other","description":"","narration":"On 3 October 2026 fifteen newspaper cuttings from the family archive, Google Drive and email are transcribed onto the wiki, from the 1891 court report to the 1989 coverage.","scenes":[],"sources":["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)","Great House Farm Wiki — Press Archive — Newspaper Transcripts (greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20261005-1","date":"2026-10-05","year":"2026","location":"Amgueddfa Cymru — Museum Wales","locationType":"other","description":"","narration":"On 5 October 2026, after three requests and two refusals, the Museum releases the Church Farm file: the 1931 letter and the records of the medieval spur and spearhead found beside the church in 1858.","scenes":[],"sources":["GHF-E106-R33 (https://greathousefarmwiki.wordpress.com/records-access-chronology/foi-reply-register/ghf-e106-r33-amgueddfa-cymru-reply-further-collections-search-following-8-september-2026-foi/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-20261006-1","date":"2026-10-06","year":"2026","location":"Legal Review","locationType":"other","description":"","narration":"On 6 October 2026 the family publish a review of the whole record from three angles: fraud, land and human rights. It identifies the 1974 licence-letter timing as an inference requiring the original papers; notes that the separate farmhouse title was later merged into BP's main title; and identifies the absence, in the material currently surfaced, of a demonstrated documentary root showing how Parcel A entered the BP chain.","scenes":[],"sources":["Legal Review — Fraud, Land and Human Rights (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-99990101-1","date":"9999-01-01","year":"present_day","location":"Where Things Stand","locationType":"other","description":"","narration":"Where things stand. The family's present case is that the documentary title to the house parcel has not yet been shown to have been fully examined in the surviving court record. The 1955, 1962, 1974 and 1980s proceedings must be read from their original files before making a broader statement about what ownership issues were or were not litigated. The 1877 agreement, 1928 change, 1938 conveyance and 1939 tenancy remain important documentary tests. BP demolished the house on 6 December 1988, immediately after the 5 December listing decision, before the building could be fully recorded. Key records are missing, and public-authority handling is now being investigated.","scenes":[{"character":"ARCHIVIST","icon":"archive","side":"left","color":"#999","text":"The chronology therefore separates what the courts decided from what the surviving documentary record can now establish. The central unresolved issue is the root of title to the farmhouse parcel, alongside the evidence about how Mary's occupation was repeatedly characterised as permissive.","position":{"x":0,"y":0}}],"sources":["Where Things Stand (https://greathousefarmwiki.wordpress.com/where-things-stand/)","Legal Review — Fraud, Land and Human Rights (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]}},{"id":"ghf-99990102-1","date":"9999-01-02","year":"present_day","location":"What the Family Seek","locationType":"other","description":"","narration":"What the family seek: a ruling that they own the house parcel; possession of the woodland and the green, or reparations where that can no longer be given; reparations for the houses built on family land; the return of estate artefacts; and a true heritage record. Every body involved is being given the chance to put things right before the family goes back to court. The Independent Complaints Reviewer deadline falls about 25 November 2026.","scenes":[],"sources":["Family Reparations & Remedy Roadmap (https://greathousefarmwiki.wordpress.com/family-reparations-remedy-roadmap/)","Where Things Stand (https://greathousefarmwiki.wordpress.com/where-things-stand/)"],"attachments":{"gallery":[],"legal":[],"news":[],"notes":[],"report":[]},"challenge":"The family's case is that fraud and concealment kept the title documents from the courts, opening the way to reopen the judgment under section 32 of the Limitation Act 1980 and the rule in Takhar v Gracefield."}];
